// Loads the Rust host compiled to WebAssembly and gives its JSON a shape.
// The files under ./wasm are generated by `just wasm` and are not committed.
import init, { demoScenario, runScenario } from "./wasm/airport_sim_wasm.js";
import wasmUrl from "./wasm/airport_sim_wasm_bg.wasm" with { type: "file" };

export async function loadSim(): Promise<void> {
  await init({ module_or_path: wasmUrl });
}

export type Reason = "maintenance" | "storm" | "curfew" | "incident" | "other";
export type Emergency = "pan_pan" | "mayday";

export interface RunwayConfig {
  low: string;
  high: string;
  heading_deg: number;
  length_m: number;
  exit_extra_ms: number;
  crosswind_limit_kt: number;
}

export interface AirportConfig {
  name: string;
  runways: RunwayConfig[];
  crossings: [string, string][];
  final_approach_nm: number;
  mayday_inspection_ms: number;
  max_arrival_hold_ms: number | null;
}

interface Movement {
  flight: string;
  aircraft: string;
  runway: string;
  at_ms: number;
  vacated_ms: number;
  delay_ms: number;
  emergency: Emergency | null;
}

export type Output =
  | { type: "accepted"; flight: string; at_ms: number }
  | { type: "rejected"; subject: string; at_ms: number; reason: string }
  | ({ type: "landed" } & Movement)
  | ({ type: "departed" } & Movement)
  | { type: "diverted"; flight: string; at_ms: number; reason: string }
  | { type: "emergency_declared"; flight: string; at_ms: number; kind: Emergency }
  | { type: "runway_closed"; runway: string; at_ms: number; reason: Reason }
  | { type: "runway_opened"; runway: string; at_ms: number; reason: Reason; open: boolean }
  | { type: "runway_inspection"; runway: string; from_ms: number; until_ms: number }
  | { type: "active_runways"; at_ms: number; runways: string[] }
  | { type: "wind_changed"; at_ms: number; direction_deg: number; speed_kt: number }
  | { type: "ground_stop_started"; at_ms: number; reason: Reason }
  | { type: "ground_stop_lifted"; at_ms: number; reason: Reason; clear: boolean };

export interface Stats {
  accepted: number;
  landed: number;
  departed: number;
  diverted: number;
  rejected: number;
  arrival_delay_ms: number;
  departure_delay_ms: number;
}

export interface Snapshot {
  now_ms: number;
  wind: { direction_deg: number; speed_kt: number };
  ground_stops: Reason[];
  runways: {
    name: string;
    active_end: string | null;
    closures: Reason[];
    inspection_until_ms: number | null;
  }[];
  queue: unknown[];
  stats: Stats;
  fingerprint: string;
}

export interface RunResult {
  outputs: Output[];
  start: Snapshot;
  end: Snapshot;
}

export interface DemoOptions {
  /** Any `u64`, so a seed printed by the command line can be replayed here. */
  seed: bigint;
  hours: number;
  arrivalsPerHour: number;
  departuresPerHour: number;
}

export interface DemoRun {
  airport: AirportConfig;
  result: RunResult;
}

/** Builds the demonstration scenario in Rust and runs it. Call `loadSim` first. */
export function runDemo(options: DemoOptions): DemoRun {
  const scenario = demoScenario(
    options.seed,
    options.hours,
    options.arrivalsPerHour,
    options.departuresPerHour,
  );
  const airport = (JSON.parse(scenario) as { airport: AirportConfig }).airport;
  const result = JSON.parse(runScenario(scenario)) as RunResult;
  return { airport, result };
}
